import { createContext, useContext, useState } from 'react';

// Step 1: Create Context
const XPContext = createContext();

// Step 2: Create Provider - holds state and provides to all children
function XPProvider({ children }) {
 const [xp, setXp] = useState(150);
 const [coins, setCoins] = useState(30);

 function addXP(amount) {
 setXp(prev => prev + amount);
 setCoins(prev => prev + Math.floor(amount/5));
 }

 return (
 <XPContext.Provider value={{ xp, coins, addXP }}>
 {children}
 </XPContext.Provider>
 );
}

// Step 3: Use context anywhere - no prop drilling!
function Navbar() {
 const { xp, coins } = useContext(XPContext); // Direct access, no props!
 return <div>⚡ {xp} XP 🪙 {coins} Coins</div>;
}

function LessonCard({ id }) {
 const { addXP } = useContext(XPContext);
 return <button onClick={() => addXP(50)}>Complete Lesson {id} +50 XP</button>;
}

function App() {
 return (
 <XPProvider>
 <Navbar /> {/* No props needed! */}
 <LessonCard id={1} /> {/* No props drilling for XP */}
 <LessonCard id={2} />
 </XPProvider>
 );
}
// Before: App -> Navbar props.xp, App -> LessonGrid -> LessonCard props.addXP - drilling!
// After: Any component uses useContext(XPContext) - direct access!

import { useState, useEffect } from 'react';

// Custom Hook 1: useLocalStorage - Reusable localStorage logic
function useLocalStorage(key, initialValue) {
 const [value, setValue] = useState(() => {
 const saved = localStorage.getItem(key);
 return saved? JSON.parse(saved) : initialValue;
 });

 useEffect(() => {
 localStorage.setItem(key, JSON.stringify(value));
 }, [key, value]);

 return [value, setValue];
}

// Custom Hook 2: useFetch - Reusable Firebase fetch logic
function useFetch(url) {
 const [data, setData] = useState(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);

 useEffect(() => {
 async function fetchData() {
 try {
 setLoading(true);
 await new Promise(r => setTimeout(r, 1000)); // Simulate fetch
 setData([{id: 1, title: "Intro"}, {id: 2, title: "JSX"}]);
 } catch (err) {
 setError("Failed to fetch");
 } finally {
 setLoading(false);
 }
 }
 fetchData();
 }, [url]);

 return { data, loading, error };
}

// Usage - Super clean!
function Dashboard() {
 const [xp, setXp] = useLocalStorage("xp", 0); // Auto saves to localStorage!
 const { data: lessons, loading } = useFetch("/api/lessons"); // Auto fetches!

 if (loading) return <p>Loading...</p>;
 return <div>XP: {xp} - {lessons?.length} lessons <button onClick={() => setXp(xp+50)}>+50 XP</button></div>;
}
