import { useState, memo, useMemo, useCallback } from 'react';

// Without memo - re-renders every time parent re-renders
function LessonCardNormal({ title }) {
 console.log(`Rendering ${title}`); // Logs every parent render, even if title same
 return <p>{title}</p>;
}

// With memo - only re-renders if title prop changes
const LessonCardMemo = memo(function LessonCard({ title }) {
 console.log(`Memo rendering ${title}`); // Only logs when title actually changes
 return <p>{title}</p>;
});

function App() {
 const [xp, setXp] = useState(0);
 const [lessons] = useState([{id: 1, title: "Intro"}, {id: 2, title: "JSX"}]);

 // useMemo - expensive calculation only runs when lessons changes, not when xp changes
 const completedCount = useMemo(() => {
 console.log("Calculating completed");
 return lessons.filter(l => l.status==='completed').length;
 }, [lessons]);

 // useCallback - function not recreated each render, so memo child doesn't re-render
 const handleComplete = useCallback((id) => {
 console.log("Complete", id);
 }, []); // Empty deps = function never changes

 return (
 <div>
 <p>XP: {xp} Completed: {completedCount}</p>
 <button onClick={() => setXp(xp+10)}>+10 XP (triggers parent re-render)</button>
 <LessonCardNormal title="Intro" /> {/* Re-renders on XP change - wasted! */}
 <LessonCardMemo title="Intro" /> {/* Does NOT re-render on XP change - optimized! */}
 </div>
 );
}
