import { Component } from 'react';

class ErrorBoundary extends Component {
 constructor(props) { super(props); this.state = { hasError: false }; }
 static getDerivedStateFromError(error) { return { hasError: true }; }
 componentDidCatch(error, info) { console.log("Error caught:", error); }
 render() {
 if (this.state.hasError) {
 return <div style={{padding: '20px', background: '#fee2e2', color: '#dc2626', borderRadius: '12px'}}><h3>Something went wrong in this lesson card</h3><button onClick={() => this.setState({hasError: false})}>Retry</button></div>;
 }
 return this.props.children;
 }
}

function BuggyLessonCard({ title }) {
 if (title===undefined) throw new Error("Title missing!"); // Simulate bug
 return <p>{title}</p>;
}

function App() {
 return (
 <div>
 <ErrorBoundary><BuggyLessonCard title="JSX" /></ErrorBoundary> {/* Works */}
 <ErrorBoundary><BuggyLessonCard title={undefined} /></ErrorBoundary> {/* Crashes but caught, shows fallback */}
 <p>Rest of app still works - not white screen!</p>
 </div>
 );
}
