import { createContext, useContext, useState, useEffect, memo, useCallback } from 'react';

// Custom Hook: useLocalStorage (reusable logic)
function useLocalStorage(key, initial) {
 const [value, setValue] = useState(() => {
 const saved = localStorage.getItem(key);
 return saved? JSON.parse(saved) : initial;
 });
 useEffect(() => { localStorage.setItem(key, JSON.stringify(value)); }, [key, value]);
 return [value, setValue];
}

// Context: Global XP store (avoid prop drilling)
const AppContext = createContext();
function AppProvider({ children }) {
 const [xp, setXp] = useLocalStorage("xp", 120);
 const [coins, setCoins] = useLocalStorage("coins", 30);
 const addXP = useCallback((amount) => {
 setXp(prev => prev + amount);
 setCoins(prev => prev + Math.floor(amount/5));
 }, [setXp, setCoins]);
 return <AppContext.Provider value={{ xp, coins, addXP }}>{children}</AppContext.Provider>;
}

// Memoized component - only re-renders if props change (performance)
