 {status==='current' && <button onClick={() => onComplete(id)} style={{background: '#61dafb', border: 'none', padding: '8px 12px', borderRadius: '8px', fontWeight: '700', marginTop: '10px'}}>Complete +50 XP</button>}
 </div>
 );
});

